{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "example-html-ppt-zhangzara-studio",
  "title": "Build a Studio Portfolio & Rate Deck like a Creative Studio Owner",
  "title_i18n": {
    "en": "Build a Studio Portfolio & Rate Deck like a Creative Studio Owner",
    "zh-CN": "像创意工作室主理人一样做作品与报价稿",
    "zh-TW": "像创意工作室主理人一样做作品与报价稿"
  },
  "version": "0.1.0",
  "description": "A photography studio's portfolio-and-rate deck — the signature work, the process, and the packages that win the brief. Built as a decision-grade design craft deck for prospective clients.",
  "description_i18n": {
    "en": "A photography studio's portfolio-and-rate deck — the signature work, the process, and the packages that win the brief. Built as a decision-grade design craft deck for prospective clients.",
    "zh-CN": "像创意工作室主理人一样做作品与报价稿——一份可商业交付的设计打磨 Deck，围绕真实主题、证据链与决策目标组织。",
    "zh-TW": "像创意工作室主理人一样做作品与报价稿——一份可商业交付的设计打磨 Deck，围绕真实主题、证据链与决策目标组织。"
  },
  "license": "MIT",
  "author": {
    "name": "Open Design",
    "url": "https://github.com/nexu-io"
  },
  "homepage": "https://github.com/nexu-io/open-design/tree/main/plugins/_official/examples/html-ppt-zhangzara-studio",
  "tags": [
    "example",
    "first-party",
    "deck",
    "marketing",
    "web",
    "studio",
    "zhangzara-studio",
    "electric",
    "bold",
    "graphic",
    "loud",
    "design-studio-credentials",
    "creative-agency-pitch",
    "html-deck",
    "html-slides",
    "zhangzara",
    "sales",
    "renewal",
    "customer",
    "html-ppt-zhangzara-studio",
    "design-craft",
    "board-upgrade-deck-rescue",
    "design",
    "brand",
    "visual-system",
    "decision-deck",
    "commercial-slide-agent"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "deck",
    "scenario": "design",
    "surface": "web",
    "preview": {
      "type": "html",
      "entry": "./example.html"
    },
    "useCase": {
      "query": {
        "en": "Create \"Build a Studio Portfolio & Rate Deck like a Creative Studio Owner\" as a decision-grade Design craft deck in this template's own visual system. Subject: A photography studio's portfolio-and-rate deck — the signature work, the process, and the packages that win the brief. Audience: prospective clients. First ask only for missing essentials: audience, decision target, source-of-truth materials, deadline, and must-keep numbers. Then produce the slide plan, written slides, visual direction, speaker-ready structure, and a critic pass against this rubric: does the deck feel authored by a senior designer rather than generated.",
        "zh-CN": "像创意工作室主理人一样做作品与报价稿。像创意工作室主理人一样做作品与报价稿——一份可商业交付的设计打磨 Deck，围绕真实主题、证据链与决策目标组织。 主题：A photography studio's portfolio-and-rate deck — the signature work, the process, and the packages that win the brief. 先确认受众、决策目标、素材来源、截止时间和必须保留的数据，再输出叙事主线、页面规划、逐页文案、视觉方向和按评审标准自检的版本。"
      },
      "exampleOutputs": [
        {
          "path": "./example.html",
          "title": "Build a Studio Portfolio & Rate Deck like a Creative Studio Owner",
          "title_i18n": {
            "en": "Build a Studio Portfolio & Rate Deck like a Creative Studio Owner",
            "zh-CN": "像创意工作室主理人一样做作品与报价稿",
            "zh-TW": "像创意工作室主理人一样做作品与报价稿"
          }
        }
      ]
    },
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "assets": [
        "./example.html"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "generate",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write"
    ],
    "category": "design-craft"
  }
}
